echo "$B64SCRIPT" | base64 -d > /opt/ping/backups/pg-backup.sh
chmod +x /opt/ping/backups/pg-backup.sh
echo "$B64SVC" | base64 -d | sudo -n tee /etc/systemd/system/pg-backup.service > /dev/null
